import csv
import gzip
import io
import os
import re
import sys
from datetime import date

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT_OWN = os.path.join(ROOT, "data", "ownership.csv.gz")
OUT_LIST = os.path.join(ROOT, "data", "company_listing.csv.gz")

OWN_COLS = ["company", "company_name", "cik", "state", "property", "aliases", "region", "relation",
            "share", "start", "end", "source", "notes", "consolidated", "discontinued", "verified", "property_id"]
LIST_COLS = ["company", "company_name", "ciks", "tickers", "exchange", "listed_start", "listed_end",
             "successor", "source", "verified", "notes"]
RELATIONS = {"owned", "leased_operated", "jv", "managed"}
STATES = set("AL AK AZ AR CA CO CT DE FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ "
             "NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY DC".split())
NV_REGIONS = {"Las Vegas Strip", "Downtown", "North Las Vegas", "Boulder Strip", "Balance of Clark County",
              "Laughlin", "Mesquite", "Reno", "Sparks", "North Lake Tahoe", "South Lake Tahoe", "Elko County",
              "Wendover", "Carson Valley Area", "Balance of Washoe", "Churchill County", "Nye County"}
MS_REGIONS = {"Northern River", "Central River", "Coastal"}
ASOF = "2026-09-23"
# listed parents that consolidate another listed company in this table (overlap allowed)
PARENT_OF = {("IEP", "TPCA")}


def _d(s):
    return date.fromisoformat(s) if s else None


def rows_as_dicts():
    return [dict(zip(OWN_COLS, r)) for r in PROPERTIES]


def validate(rows, listing):
    errs = []
    comps = {l[0] for l in listing}
    for i, r in enumerate(rows):
        tag = f"row {i} {r['company']} {r['property']}"
        if r["company"] not in comps:
            errs.append(f"{tag}: company missing from LISTING")
        if r["state"] not in STATES:
            errs.append(f"{tag}: bad state")
        if r["relation"] not in RELATIONS:
            errs.append(f"{tag}: bad relation {r['relation']}")
        if not (0 < float(r["share"]) <= 1) and not (r["relation"] == "managed" and float(r["share"]) == 0):
            errs.append(f"{tag}: bad share")
        if r["consolidated"] not in (0, 1) or r["discontinued"] not in (0, 1):
            errs.append(f"{tag}: bad consolidated/discontinued flag")
        if r["discontinued"] == 1 and r["consolidated"] != 1:
            errs.append(f"{tag}: discontinued rows must be consolidated")
        if r["verified"] not in ("sec", "web", "knowledge"):
            errs.append(f"{tag}: bad verified flag")
        for k in ("start", "end"):
            if r[k] and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", r[k]):
                errs.append(f"{tag}: bad {k} {r[k]}")
        if r["start"] and r["end"] and _d(r["start"]) >= _d(r["end"]):
            errs.append(f"{tag}: start >= end")
        if r["end"] and r["end"] < "2012-01-01":
            errs.append(f"{tag}: ends before 2012")
        if r["start"] and r["start"] > ASOF:
            errs.append(f"{tag}: starts after as-of date")
        if r["state"] == "NV" and r["region"] not in NV_REGIONS:
            errs.append(f"{tag}: NV region '{r['region']}' not an NGCB area")
        if r["state"] == "MS":
            parts = r["region"].split("|")
            if len(parts) != 2 or parts[1] not in MS_REGIONS:
                errs.append(f"{tag}: MS region must be County|Region")
        if r["state"] == "CO" and not r["region"]:
            errs.append(f"{tag}: CO town missing")
        if not r["source"]:
            errs.append(f"{tag}: no source")
    # the same company must not hold the same property twice at the same time
    by = {}
    for r in rows:
        by.setdefault((r["company"], r["property_id"]), []).append(r)
    for k, rs in by.items():
        rs = sorted(rs, key=lambda r: r["start"] or "0000")
        for a, b in zip(rs, rs[1:]):
            if not a["end"] or (b["start"] or "0000") < a["end"]:
                errs.append(f"overlap {k}: {a['start']}-{a['end']} vs {b['start']}-{b['end']}")
    # at most one consolidating owner per property at any time (JV partners excepted)
    byp = {}
    for r in rows:
        if r["consolidated"] == 1:
            byp.setdefault(r["property_id"], []).append(r)
    for pid, rs in byp.items():
        rs = sorted(rs, key=lambda r: r["start"] or "0000")
        for a, b in zip(rs, rs[1:]):
            pair = {(a["company"], b["company"]), (b["company"], a["company"])}
            if pair & PARENT_OF:
                continue
            if not a["end"] or (b["start"] or "0000") < a["end"]:
                errs.append(f"two consolidating holders of {pid}: {a['company']} {a['start']}-{a['end']} "
                            f"vs {b['company']} {b['start']}-{b['end']}")
    return errs


def write_csv_gz(path, cols, rows):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(cols)
    for r in rows:
        w.writerow([("" if r[c] is None else r[c]) for c in cols])
    with gzip.open(path, "wt", encoding="utf-8", newline="") as f:
        f.write(buf.getvalue())


def main():
    rows = rows_as_dicts()
    listing = [dict(zip(LIST_COLS, l)) for l in LISTING]
    errs = validate(rows, LISTING)
    if errs:
        print("VALIDATION PROBLEMS:")
        for e in errs:
            print("  ", e)
        if "--force" not in sys.argv:
            sys.exit(1)
    rows.sort(key=lambda r: (r["company"], r["state"], r["property"], r["start"] or ""))
    write_csv_gz(OUT_OWN, OWN_COLS, rows)
    write_csv_gz(OUT_LIST, LIST_COLS, listing)
    n_ver = {}
    for r in rows:
        n_ver[r["verified"]] = n_ver.get(r["verified"], 0) + 1
    print(f"wrote {OUT_OWN}: {len(rows)} rows, {len({r['company'] for r in rows})} companies, "
          f"{len({r['property_id'] for r in rows})} distinct properties; verified: {n_ver}")
    print(f"wrote {OUT_LIST}: {len(listing)} companies")


if __name__ == "__main__":
    main()
